unsigned int dp[1 << 26];
int need[26], deg[26], z[N];
set<int> g[26];
void solve(int CASE)
{
    string s; cin >> s;
    int n = s.size();
    getZ(s);
    s = ' ' + s;
    fa(i, 2, n) {
        int x = z[i - 1] + 1, y = i + z[i - 1];
        if (y > n) {
            cout << 0 << endl;
            return;
        }
        if (!g[s[x] - 'a'].count(s[y] - 'a')) {
            g[s[x] - 'a'].insert(s[y] - 'a');
            deg[s[y] - 'a']++;
        }
    }
    var Q = queue<int>();
    fa(i, 0, 25)if (deg[i] == 0)Q.push(i);
    while (Q.size()) {
        int now = Q.front();
        Q.pop();
        for (int to : g[now]) {
            deg[to]--;
            need[to] |= (need[now] | (1 << now));
            if (deg[to] == 0)Q.push(to);
        }
    }
    fa(i, 0, 25)if (deg[i]) {
        cout << 0 << endl;
        return;
    }
    dp[0] = 1;
    fa(st, 0, (1 << 26) - 1) {
        fa(i, 0, 25)if (st & (1 << i)) {
            int nst = (st ^ (1 << i));
            if ((nst & need[i]) == need[i])dp[st] += dp[nst];
        }
    }
    cout << dp[(1 << 26) - 1] << endl;
    return;
}
